    const TIDAL_ARTIST_ABOUT = {"After Hours Player": "After Hours Player soundtracks late 90s rap nights with leather-seat bass. The afterparty starts when this plays.", "Blue Note": "Blue Note compiles jazz classics the way a good DJ closes the night: standards first, fireworks later. Every cut earned its place over decades of dance floors.", "Cassette Kisses": "Cassette Kisses seals sweet 80s pop with lipstick and tape hiss. Rewind to the good part.", "Corner Lessons": "Corner Lessons teaches daytime rap anthems with the windows down. School is in session on every block.", "Electric Avenue": "Electric Avenue wires synth pop selection into streetlight anthems. Neon signs make the best choruses.", "Flashback Fever": "Flashback Fever spins a pop rewind collection with the best hooks of every decade. The fever breaks on the dance floor.", "Golden Tape": "Golden Tape rewinds the mixtape era: hiss, bass and glory. Dubbed twice, loved forever.", "Late Night Grooves": "Late Night Grooves pours smooth sounds for quiet moments after midnight. Low light, high fidelity.", "Lazy Sundays": "Lazy Sundays plans a musical getaway in jazz, chill and soul. No alarms, no skips, no hurry.", "Midnight Cipher": "Midnight Cipher hosts underground rap sessions where the beat never blinks. Ciphers, not singles.", "Midnight Drive": "Midnight Drive scores electronic afterdark hours with long headlights of synth. The city looks better at 3 AM through their windshield.", "Modern Legends": "Modern Legends carries the hip hop essentials forward: hard drums, soul loops and bars with weight. The same crew appears in the local shelf and on TIDAL with different sessions.", "Neon Pulse": "Neon Pulse soundtracks synthwave nights with overdrive hearts and neon circuitry. Their records play at one speed: after midnight.", "Pulse Array": "Pulse Array sequences techno with laboratory patience and warehouse payoff. Every pattern locks, every break releases.", "Rooftop Rhymes": "Rooftop Rhymes collects 90s hip-hop essentials with skyline views. Antennas up, drums out.", "Starlight Boulevard": "Starlight Boulevard reflects city pop back at the night in chrome and rain. Cruise tempo, always.", "The Marlowe Ensemble": "The Marlowe Ensemble is a modern jazz collective with lush arrangements and long improvisations. Velvet Skyline paints the city at dusk in brushed cymbals and low brass.", "Velvet Satellite": "Velvet Satellite orbits midnight pop glamour in velvet and chrome. Signals from a lovelier frequency."};
    function tidalSimilarFor(artistId) {
        const self = TIDAL_ARTISTS.find(a => a.id === artistId);
        if (!self) return [];
        const sameGenre = (a) => (a.genres || []).some(g => (self.genres || []).includes(g));
        return TIDAL_ARTISTS
            .filter(a => a.id !== artistId)
            .sort((a, b) => (sameGenre(a) ? 0 : 1) - (sameGenre(b) ? 0 : 1))
            .slice(0, 6)
            .map(a => ({ type: 'artist', artist: a.name, provider_artist_id: a.id, art_url: a.art_url || a.image_url || '' }));
    }

